using Scheduling.Legacy;

namespace Scheduling;

/// <summary>Sends reminders for upcoming jobs.</summary>
public sealed class ReminderSender
{
    private readonly INotificationSender _notifications;

    public ReminderSender(INotificationSender notifications) =>
        _notifications = notifications;

    public bool Send(Job job, string recipient)
    {
        // TODO: localise the reminder text per recipient
        return _notifications.Send(recipient, $"Reminder for {job.Id}");
    }
}

public interface INotificationSender
{
    bool Send(string recipient, string message);
}
